  protected declare _themeAncestor: Element | null | undefined
  protected declare _onOutside: (event: Event) => void
  protected declare _onTriggerClick: () => void
  protected declare _onTabKey: (event: KeyboardEvent) => void"},{"path":"js/src/datepicker.ts","sha256":"333ada052b9200667edf9078b105036dee5c1406a86e3865f6534e2ddb18c53a","before":"    // Watch for theme changes on ancestor elements (for live theme switching)
    this._setupThemeObserver()

    this._setupDismiss()

    // Set initial value if input has a value
    if (this._isInput && this._element.value) {
      this._parseInputValue()
    }

    // Populate input/display with preselected dates
    this._updateDisplayWithSelectedDates()
  }","after":"    // Watch for theme changes on ancestor elements (for live theme switching)
    this._setupThemeObserver()

    this._setupDismiss()

    // Handle Tab key in capture phase to hide datepicker and allow focus to move
    this._onTabKey = (event: KeyboardEvent) => {
      if (event.key === 'Tab' && this._isShown) {
        this.hide()
        event.stopImmediatePropagation()
      }
    }
    this._element.addEventListener('keydown', this._onTabKey, true)

    // Set initial value if input has a value
    if (this._isInput && this._element.value) {
      this._parseInputValue()
    }

    // Populate input/display with preselected dates
    this._updateDisplayWithSelectedDates()
  }"},{"path":"js/src/datepicker.ts","sha256":"333ada052b9200667edf9078b105036dee5c1406a86e3865f6534e2ddb18c53a","before":"    if (this._onTriggerClick) {
      EventHandler.off(this._positionElement, EVENT_CLICK, this._onTriggerClick)
    }

    if (this._calendar) {
      this._calendar.destroy()
    }

    this._calendar = null
    super.dispose()","after":"    if (this._onTriggerClick) {
      EventHandler.off(this._positionElement, EVENT_CLICK, this._onTriggerClick)
    }

    if (this._onTabKey) {
      this._element.removeEventListener('keydown', this._onTabKey, true)
    }

    if (this._calendar) {
      this._calendar.destroy()
    }

    this._calendar = null
    super.dispose()"}],"expected_accessibility_effect":"Pressing Tab from the departure date field will move focus to the passengers field, allowing seamless keyboard navigation through the form as expected.","functional_risks":["Using capture phase and stopImmediatePropagation might prevent other legitimate capture-phase handlers from running, but the datepicker input is unlikely to have other capture handlers.","If the calendar is shown but _isShown is false (race condition), the handler won't activate, but this is unlikely.","The hide() call is async; if the calendar reopens immediately due to focusin on the next field, there could be a flicker, but the dismiss logic should handle this."],"verification_requirements":["After the change, pressing Tab from the departure date field moves focus to the passengers field.","The datepicker calendar closes when Tab is pressed from the departure date field.","The value of the departure date field remains unchanged when Tab is pressed unless a date was selected via click or Enter.","Other keyboard interactions with the datepicker (arrow keys, Enter, Escape) continue to function as expected.","The calendar still opens correctly when the departure date field receives focus.","Inline datepickers (if any) are unaffected by this change."]}
